select * from customer
--Q1. What is the total revenue generated by male vs. female customers?
select gender, sum(purchase_amount) as 'total_revenue' from customer group by gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 
select customer_id, purchase_amount from customer where discount_applied= 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select top 5 item_purchased, avg(review_rating) as 'AVG product Rating' from customer group by item_purchased order by avg(review_rating) Desc;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select avg(purchase_amount) as 'Average_purchase_amount', shipping_type from customer where shipping_type='Express' or shipping_type='Standard' group by shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
select subscription_status, count(customer_id) as 'Total_customers',avg(purchase_amount) as 'average_purchase_amount', sum(purchase_amount) as 'Total_purchase_amount' from customer group by subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select top 5 item_purchased, count(item_purchased) as 'count_of_items' from customer where discount_applied= 'Yes' group by item_purchased order by count(item_purchased) desc;
SELECT TOP 5 
    item_purchased,
    COUNT(*) AS total_purchases,
    SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) AS discounted_purchases,
    (SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) * 100.0 / COUNT(*)) AS discount_percentage
FROM customer
GROUP BY item_purchased
ORDER BY discount_percentage DESC;

--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment.
with customer_type as (
SELECT customer_id, previous_purchases,
CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer)
select customer_segment,count(*) AS "Number of Customers" 
from customer_type 
group by customer_segment;

--Q8. What are the top 3 most purchased products within each category? 
with all_item_count as (select category,item_purchased, count(item_purchased) as count_of_item from customer group by category, item_purchased ),

abc as ( select ROW_NUMBER() over ( partition by category order by count_of_item Desc) as ranked_item, item_purchased  from all_item_count) 

SELECT *
FROM abc
WHERE ranked_item <= 3;


--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status, count(customer_id) AS repeat_buyers
from customer 
where previous_purchases > 5 
group by subscription_status;

--Q10. What is the revenue contribution of each age group? 
select sum(purchase_amount) as 'total_revenus', age_group from customer group by age_group order by total_revenus desc;

